CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA core;
CREATE SCHEMA iam;
CREATE SCHEMA copy;
CREATE SCHEMA trade;
CREATE SCHEMA legacy_neon;
CREATE TABLE core.schema_migration(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
INSERT INTO core.schema_migration(version) VALUES ('999_dr_fixture');
CREATE TABLE iam.customer_identity(customer_id uuid PRIMARY KEY, email text NOT NULL);
INSERT INTO iam.customer_identity VALUES ('00000000-0000-0000-0000-000000000001', 'fixture@example.invalid');
CREATE TABLE copy.alpaca_oauth_token(customer_id uuid PRIMARY KEY REFERENCES iam.customer_identity(customer_id), ciphertext text NOT NULL);
INSERT INTO copy.alpaca_oauth_token VALUES ('00000000-0000-0000-0000-000000000001', 'fixture-ciphertext-not-a-key');
CREATE TABLE trade.order_intent(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, state text NOT NULL);
CREATE TABLE trade.broker_order(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, intent_id bigint REFERENCES trade.order_intent(id));
CREATE TABLE trade.fill(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id bigint REFERENCES trade.broker_order(id));
CREATE TABLE trade.broker_activity_fact(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, kind text NOT NULL);
INSERT INTO trade.broker_activity_fact(kind) VALUES ('TEST_FIXTURE');
CREATE TABLE legacy_neon.import_batch(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, source text NOT NULL);
INSERT INTO legacy_neon.import_batch(source) VALUES ('TEST_FIXTURE');
CREATE TABLE legacy_neon.artifact_record(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, batch_id bigint REFERENCES legacy_neon.import_batch(id));
INSERT INTO legacy_neon.artifact_record(batch_id) VALUES (1);
CREATE VIEW core.migration_count AS SELECT count(*) AS count FROM core.schema_migration;
CREATE FUNCTION core.noop_trigger() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NEW; END $$;
CREATE TRIGGER customer_noop BEFORE INSERT ON iam.customer_identity FOR EACH ROW EXECUTE FUNCTION core.noop_trigger();
